/* True on the frame the rest of the conditions start holding, and not again until they stop */
static MOD_UNUSED int trigger_once(int* state, int value) {
    const int fired = value != 0 && *state == 0;
    *state = value != 0;
    return fired;
}

/* rand() is seeded once, on the first draw */
static MOD_UNUSED int mod_random(int range) {
    static int seeded = 0;
    if (seeded == 0) { srand((unsigned)time(0)); seeded = 1; }
    return range > 0 ? rand() % range : 0;
}

static MOD_UNUSED float mod_random01(void) {
    return (float)mod_random(10000) / 10000.0f;
}

/* True once every `seconds`, counting from the first frame; the leftover is kept so a slow
   frame does not lose time. A state below zero means the first period has not started yet */
static MOD_UNUSED int every_seconds(float* left, float seconds) {
    if (seconds <= 0.0f) return 1;
    if (*left < 0.0f) {
        *left = seconds;
        return 0;
    }
    *left -= mod_delta;
    if (*left > 0.0f) return 0;
    *left += seconds;
    return 1;
}
